begin;
select set_config('ls.owner',gen_random_uuid()::text,true),set_config('ls.other',gen_random_uuid()::text,true),set_config('ls.known',gen_random_uuid()::text,true),set_config('ls.unknown',gen_random_uuid()::text,true),set_config('ls.tiny',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('ls.owner')::uuid,'loss-a@example.invalid'),(current_setting('ls.other')::uuid,'loss-b@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('ls.owner'),'role','authenticated')::text,true);set local role authenticated;
insert into public.products(id,name,barcode,sale_price) values(current_setting('ls.known')::uuid,'Original snapshot name','00123',1000),(current_setting('ls.unknown')::uuid,'Unknown opening',null,1000),(current_setting('ls.tiny')::uuid,'Tiny zero cost',null,1000);
do $$declare p uuid:=current_setting('ls.known')::uuid;u uuid:=current_setting('ls.unknown')::uuid;t uuid:=current_setting('ls.tiny')::uuid;today date:=(now() at time zone 'Asia/Baghdad')::date;x jsonb;v bigint;loss uuid:=gen_random_uuid();n bigint;qty bigint;begin
 x:=public.get_inventory_loss_report(today,today);if x->>'count'<>'0' or x->>'known_cost'<>'0' or x->>'complete'<>'true' then raise exception 'empty report';end if;
 perform public.post_purchase(gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',p,'quantity_units',4000,'unit_cost',500)),'','','');
 select max(movement_no) into v from public.stock_movements where product_id=p;
 perform public.post_stock_waste(loss,p,4000,v,1000,'damage evidence');perform public.post_stock_waste(loss,p,4000,v,1000,'damage evidence');
 select max(movement_no) into v from public.stock_movements where product_id=p;
 perform public.post_stock_adjustment(gen_random_uuid(),p,3000,v,2500,'count short');
 select max(movement_no) into v from public.stock_movements where product_id=p;
 perform public.post_stock_adjustment(gen_random_uuid(),p,2500,v,3000,'positive count excluded');
 perform public.post_stock_adjustment(gen_random_uuid(),u,0,0,2000,'unknown opening');select max(movement_no) into v from public.stock_movements where product_id=u;
 perform public.post_stock_waste(gen_random_uuid(),u,2000,v,500,'unknown cost loss');
 perform public.post_purchase(gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',t,'quantity_units',1,'unit_cost',1)),'','','');select max(movement_no) into v from public.stock_movements where product_id=t;
 perform public.post_stock_waste(gen_random_uuid(),t,1,v,1,'genuine zero cost');
 update public.products set name='Changed catalogue name' where id=p;
 select sum(quantity_units) into qty from public.product_stock;select count(*) into n from public.stock_movements;
 x:=public.get_inventory_loss_report(today,today);
 if x->>'count'<>'4' or x->>'known_count'<>'3' or x->>'known_cost'<>'750' or x->>'complete'<>'false' then raise exception 'loss totals';end if;
 if x->'waste'->>'count'<>'3' or x->'waste'->>'known_count'<>'2' or x->'waste'->>'known_cost'<>'500' or x->'count_shortage'->>'known_cost'<>'250' then raise exception 'kind subtotals';end if;
 if not exists(select 1 from jsonb_array_elements(x->'rows') r where r->>'product_id'=p::text and r->>'name'='Original snapshot name' and r->>'barcode'='00123') then raise exception 'snapshot changed';end if;
 if not exists(select 1 from jsonb_array_elements(x->'rows') r where r->>'product_id'=t::text and r->>'cost_iqd'='0' and r->>'coverage'='known') then raise exception 'zero confused unknown';end if;
 if not exists(select 1 from jsonb_array_elements(x->'rows') r where r->>'product_id'=u::text and r->'cost_iqd'='null'::jsonb) then raise exception 'unknown invented';end if;
 if (select count(*) from public.stock_movements)<>n or (select sum(quantity_units) from public.product_stock)<>qty or exists(select 1 from public.cash_movements) then raise exception 'read mutated business';end if;
 begin perform public.get_inventory_loss_report(today,today+366);raise exception 'long range';exception when raise_exception then if sqlerrm<>'loss_invalid_range' then raise;end if;end;
 begin perform public.get_inventory_loss_report(null,today);raise exception 'null range';exception when raise_exception then if sqlerrm<>'loss_invalid_range' then raise;end if;end;
end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('ls.other'),'role','authenticated')::text,true);set local role authenticated;
do $$begin if public.get_inventory_loss_report((now() at time zone 'Asia/Baghdad')::date,(now() at time zone 'Asia/Baghdad')::date)->>'count'<>'0' then raise exception 'owner isolation';end if;end $$;
reset role;select set_config('request.jwt.claims','{}',true);set local role authenticated;
do $$begin begin perform public.get_inventory_loss_report((now() at time zone 'Asia/Baghdad')::date,(now() at time zone 'Asia/Baghdad')::date);raise exception 'no uid';exception when raise_exception then if sqlerrm<>'loss_auth_required' then raise;end if;end;end $$;
reset role;set local role anon;
do $$begin begin perform public.get_inventory_loss_report((now() at time zone 'Asia/Baghdad')::date,(now() at time zone 'Asia/Baghdad')::date);raise exception 'anon';exception when insufficient_privilege then null;end;end $$;
reset role;
select 'PASS: known/unknown/zero costs, waste/count separation, positive counts excluded, saved names, retries, date ranges, no writes, owner isolation' as verification;
rollback;
